create temp table from_model as select * from api.cmd_review_collect_dataset_targets('[{"table":"lifecyclemodels","id":"11290000-0000-4000-8000-000000000001","version":"06.00.000","is_root":true}]',false);
create temp table from_process as select * from api.cmd_review_collect_dataset_targets('[{"table":"processes","id":"11290000-0000-4000-8000-000000000002","version":"08.00.000","is_root":true}]',false);
select is((select count(*) from from_model),5::bigint,'Model root includes current outputs, allocated provider and required external input');
select results_eq('select table_name,dataset_id,dataset_version from from_model order by 1,2,3','select table_name,dataset_id,dataset_version from from_process order by 1,2,3','Model and independent-UUID result roots collect the same exact set');
